import type * as OpenCode from "@opencode/plugin"
import { resolveRoots } from "./access.ts"
import type { PermissionAssert } from "./access.ts"
import { runExcerpt } from "./excerpt.ts"

const DESCRIPTION =
  "Read one explicitly requested, inclusive line range (1-based, max 80 lines) from a single UTF-8 text file. Requires the read_excerpt permission, and external_directory permission for paths outside the project. Environment files (.env*) are blocked unless the name ends in .example. No glob, directory listing, URL, shell or Git access; no implicit full-file reads."

const INPUT_SCHEMA = {
  type: "object",
  properties: {
    path: {
      type: "string",
      description:
        "Literal path of a single file. Relative paths are resolved against the session/project directory.",
    },
    start_line: {
      type: "integer",
      minimum: 1,
      description: "First line to read, 1-based and inclusive.",
    },
    end_line: {
      type: "integer",
      minimum: 1,
      description: "Last line to read, inclusive. Must be >= start_line and start_line + 79 at most.",
    },
  },
  required: ["path", "start_line", "end_line"],
  additionalProperties: false,
}

export const ReadExcerptPlugin: OpenCode.Plugin.Plugin = {
  id: "opencode-read-excerpt",
  async setup(ctx) {
    await ctx.tool.transform((editor) => {
      editor.add({
        name: "read_excerpt",
        description: DESCRIPTION,
        // The framework accepts plain JSON schema values but types the field as a codec/standard-schema union.
        input: INPUT_SCHEMA as unknown as never,
        options: { permission: "read_excerpt", codemode: false },
        execute: async (input, context) => {
          let sessionDirectory: string | undefined
          try {
            const session = await ctx.session.get({ sessionID: context.sessionID })
            sessionDirectory = session.location.directory
          } catch {
            sessionDirectory = undefined
          }

          const candidates = [sessionDirectory ?? ctx.location.directory, ctx.location.project.directory]
          const directories = [
            ...new Set(candidates.filter((directory) => typeof directory === "string" && directory.length > 0)),
          ]
          const roots = await resolveRoots(directories)

          const assert: PermissionAssert = async (request) => {
            // IDs are branded strings in the framework types; the request carries plain strings.
            await ctx.permission.assert({
              sessionID: request.sessionID,
              agent: request.agent,
              action: request.action,
              resources: request.resources,
              save: request.save,
              source: request.source,
            } as Parameters<typeof ctx.permission.assert>[0])
          }

          return await runExcerpt(
            input,
            {
              sessionID: context.sessionID,
              agent: context.agent,
              messageID: context.messageID,
              id: context.id,
              signal: context.signal,
              roots,
            },
            assert,
          )
        },
      })
    })
  },
}

export default ReadExcerptPlugin
